import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function InfluencerProfile() {
    const navigate = useNavigate();
    const fileInputRef = useRef(null);
    const [profileData, setProfileData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        platform: '',
        accountLink: '',
        bio: '',
        profileImage: null
    });
    const [loading, setLoading] = useState(false);
    const [stats, setStats] = useState({
        posts: 0,
        followers: 0,
        views: 0
    });
    const [editing, setEditing] = useState(false);
    const [previewImage, setPreviewImage] = useState(null);
    const [imageLoaded, setImageLoaded] = useState(false);
    const [activeTab, setActiveTab] = useState('posts'); // 'posts', 'followers', or 'views'
    const [reels, setReels] = useState([]);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        loadUserProfile();
        loadInfluencerStats();
        loadInfluencerReels();
    }, []);

    const loadUserProfile = () => {
        try {
            const storedUser = localStorage.getItem('studioUser');
            if (storedUser) {
                const user = JSON.parse(storedUser);
                setProfileData({
                    firstName: user.firstname || '',
                    lastName: user.lastname || '',
                    email: user.email || '',
                    phone: user.telephone || '',
                    platform: user.platform || '',
                    accountLink: user.account_link || '',
                    bio: user.bio || '',
                    profileImage: user.image || null
                });
                setPreviewImage(user.image || null);
                // Mark image as loaded once we have the data
                if (user.image) {
                    setImageLoaded(true);
                }
            }
        } catch (error) {
            console.error('Error loading user profile:', error);
            toast.error('Failed to load profile data');
        }
    };

    const loadInfluencerStats = async () => {
        try {
            // Fetch real influencer reels data
            const response = await ApiService.getInfluencerReels();
            
            if (response.success) {
                const reels = response.data;
                
                // Calculate real stats
                const posts = reels.length;
                let totalViews = 0;
                let totalLikes = 0;
                
                // Sum up views and likes from all reels
                reels.forEach(reel => {
                    totalViews += reel.views || 0;
                    totalLikes += reel.likes || 0;
                });
                
                // Calculate approximate followers based on engagement
                // This provides more realistic numbers than fixed dummy values
                let followers = 0;
                
                if (posts > 0) {
                    // Estimate followers based on engagement rate and posts
                    // Higher engagement and more posts typically mean more followers
                    const avgViewsPerPost = totalViews / posts;
                    const avgLikesPerPost = totalLikes / posts;
                    
                    // Simple algorithm to estimate followers based on engagement
                    followers = Math.max(100, Math.round(avgViewsPerPost * 0.8 + avgLikesPerPost * 3));
                } else {
                    // Default values when no posts exist
                    followers = 150;
                }
                
                setStats({
                    posts: posts,
                    followers: followers,
                    views: totalViews
                });
            } else {
                // Fallback to mock stats if API call fails
                setStats({
                    posts: 12,
                    followers: 250,
                    views: 45600
                });
            }
        } catch (error) {
            console.error('Error loading influencer stats:', error);
            // Fallback to mock stats if API call fails
            setStats({
                posts: 12,
                followers: 250,
                views: 45600
            });
        }
    };

    const loadInfluencerReels = async () => {
        try {
            const response = await ApiService.getInfluencerReels();
            if (response.success) {
                setReels(response.data);
            }
        } catch (error) {
            console.error('Error loading influencer reels:', error);
        }
    };

    const handlePostsClick = () => {
        setActiveTab('posts');
    };

    const handleFollowersClick = () => {
        setActiveTab('followers');
    };

    const handleViewsClick = () => {
        setActiveTab('views');
    };

    // Function to render video player for a reel
    const renderVideoPlayer = (reel) => {
        // Check if video URL exists and is valid
        if (!reel.video_url || reel.video_url === 'null' || reel.video_url === 'undefined') {
            return (
                <div className="ratio ratio-16x9 bg-dark rounded d-flex align-items-center justify-content-center">
                    <div className="text-white">No video available</div>
                </div>
            );
        }
        
        // Additional check for URL validity
        try {
            new URL(reel.video_url);
        } catch (e) {
            console.error('Invalid video URL:', reel.video_url);
            return (
                <div className="ratio ratio-16x9 bg-dark rounded d-flex align-items-center justify-content-center">
                    <div className="text-white">Invalid video URL</div>
                </div>
            );
        }
        
        return (
            <div className="video-player-container mb-2">
                <div className="ratio ratio-16x9 bg-dark rounded">
                    <video 
                        width="100%" 
                        height="100%" 
                        controls
                        poster={reel.thumbnail || ''}
                        style={{ objectFit: 'cover' }}
                        className="rounded w-100 h-100"
                        onError={(e) => {
                            console.error('Video loading error:', e);
                            console.log('Video URL that failed:', reel.video_url);
                        }}
                        onLoadedData={(e) => {
                            console.log('Video loaded successfully');
                        }}
                    >
                        <source src={reel.video_url} type="video/mp4" />
                        Your browser does not support the video tag.
                    </video>
                </div>
                <div className="mt-2">
                    <h6 className="text-truncate mb-1" title={reel.title}>{reel.title}</h6>
                    <div className="d-flex justify-content-between small text-muted">
                        <span>{new Date(reel.created_at).toLocaleDateString()}</span>
                        <span>{reel.views || 0} views</span>
                    </div>
                </div>
            </div>
        );
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleImageLoad = () => {
        setImageLoaded(true);
    };

    const handleFileChange = async (e) => {
        const file = e.target.files[0];
        if (file) {
            // Validate file type
            if (!file.type.match('image.*')) {
                toast.error('Please select an image file (JPG, PNG, etc.)');
                return;
            }
            
            // Validate file size (5MB max)
            if (file.size > 5 * 1024 * 1024) {
                toast.error('File size exceeds 5MB limit');
                return;
            }
            
            setLoading(true);
            
            try {
                // Upload the profile image to the server
                const response = await ApiService.uploadProfileImage(file);
                
                if (response.success) {
                    // Update preview
                    const imageUrl = URL.createObjectURL(file);
                    setPreviewImage(imageUrl);
                    
                    // Update profile data with the new image path
                    setProfileData(prev => ({ 
                        ...prev, 
                        profileImage: response.imagePath
                    }));
                    
                    // Update localStorage with the new image path
                    const storedUser = localStorage.getItem('studioUser');
                    if (storedUser) {
                        const user = JSON.parse(storedUser);
                        const updatedUser = {
                            ...user,
                            image: response.imagePath
                        };
                        localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                        
                        // Dispatch a custom event to notify other components of the user update
                        window.dispatchEvent(new Event('userUpdated'));
                    }
                    
                    // Reload stats to reflect any changes
                    loadInfluencerStats();
                    
                    toast.success('Profile picture updated successfully!');
                } else {
                    toast.error(response.message || 'Failed to upload profile picture');
                }
            } catch (error) {
                console.error('Profile image upload error:', error);
                toast.error('Failed to upload profile picture: ' + (error.message || 'Unknown error'));
            } finally {
                setLoading(false);
            }
        }
    };

    const triggerFileSelect = () => {
        if (!loading) {
            fileInputRef.current.click();
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        setLoading(true);
        
        try {
            // Update localStorage with the new data
            const storedUser = localStorage.getItem('studioUser');
            if (storedUser) {
                const user = JSON.parse(storedUser);
                const updatedUser = {
                    ...user,
                    firstname: profileData.firstName,
                    lastname: profileData.lastName,
                    email: profileData.email,
                    telephone: profileData.phone,
                    platform: profileData.platform,
                    account_link: profileData.accountLink,
                    bio: profileData.bio,
                    image: previewImage || profileData.profileImage
                };
                localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                
                // Dispatch a custom event to notify other components of the user update
                window.dispatchEvent(new Event('userUpdated'));
            }
            
            toast.success('Profile updated successfully!');
            setEditing(false);
            
            // Reload stats after profile update
            loadInfluencerStats();
        } catch (error) {
            console.error('Profile update error:', error);
            toast.error('Failed to update profile: ' + (error.message || 'Unknown error'));
        } finally {
            setLoading(false);
        }
    };

    const handleEditProfileClick = () => {
        // Navigate to the update profile page
        navigate('/studio/influencer/update-profile');
    };

    const displayName = `${profileData.firstName || ''} ${profileData.lastName || ''}`.trim() || 'Influencer';
    const displayEmail = profileData.email || '';
    const displayPhone = profileData.phone || 'Not provided';
    // Use the uploaded image if available, otherwise fallback to default
    const profileImageUrl = previewImage || profileData.profileImage || '/assets/images/users/avatar-1.jpg';

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Influencer Profile</h4>
                </div>
            </div>

            {/* Hidden file input */}
            <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                style={{ display: 'none' }}
                disabled={loading}
            />

            {/* Profile Header Card */}
            <div className="col-lg-12">
                <div className="card overflow-hidden">
                    <div className="card-body p-0">
                        <div className="bg-primary profile-bg rounded-top position-relative" style={{ height: '200px' }}>
                            <div 
                                className="avatar-xl mx-auto border border-light border-3 rounded-circle position-absolute top-100 start-50 translate-middle"
                                style={{ width: '120px', height: '120px', cursor: loading ? 'not-allowed' : 'pointer' }}
                                onClick={triggerFileSelect}
                            >
                                {/* Hidden default avatar that shows while loading */}
                                {!imageLoaded && (
                                    <div 
                                        className="rounded-circle bg-light d-flex align-items-center justify-content-center"
                                        style={{ width: '120px', height: '120px' }}
                                    >
                                        <i className="ri-user-line ri-2x text-muted"></i>
                                    </div>
                                )}
                                
                                {/* Profile image with onLoad handler */}
                                <img 
                                    src={profileImageUrl} 
                                    alt={displayName} 
                                    className="rounded-circle"
                                    style={{ 
                                        width: '120px', 
                                        height: '120px', 
                                        objectFit: 'cover',
                                        display: imageLoaded ? 'block' : 'none'
                                    }}
                                    onLoad={handleImageLoad}
                                    onError={() => setImageLoaded(true)}
                                />
                                <div 
                                    className="position-absolute bottom-0 end-0 bg-primary rounded-circle d-flex align-items-center justify-content-center"
                                    style={{ width: '30px', height: '30px', cursor: loading ? 'not-allowed' : 'pointer' }}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        if (!loading) {
                                            triggerFileSelect();
                                        }
                                    }}
                                >
                                    {loading ? (
                                        <span className="spinner-border spinner-border-sm text-white" role="status"></span>
                                    ) : (
                                        <i className="ri-camera-fill text-white"></i>
                                    )}
                                </div>
                            </div>
                        </div>
                        <div className="mt-5 px-4 pb-4">
                            <div className="text-center mb-4">
                                <h4 className="mb-2 fw-semibold">
                                    {displayName}
                                </h4>
                                <p className="text-muted mb-3">{displayEmail}</p>
                                
                                {/* Stats */}
                                <div className="row g-3 mt-4">
                                    <div className="col-lg-3 col-6">
                                        <div 
                                            className={`border rounded p-3 cursor-pointer ${activeTab === 'posts' ? 'bg-primary text-white' : ''}`}
                                            onClick={handlePostsClick}
                                            style={{ cursor: 'pointer' }}
                                        >
                                            <h5 className="mb-1 fw-bold">{stats.posts}</h5>
                                            <p className={`mb-0 small ${activeTab === 'posts' ? 'text-white' : 'text-muted'}`}>Posts</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div 
                                            className={`border rounded p-3 cursor-pointer ${activeTab === 'followers' ? 'bg-primary text-white' : ''}`}
                                            onClick={handleFollowersClick}
                                            style={{ cursor: 'pointer' }}
                                        >
                                            <h5 className="mb-1 fw-bold">
                                                {stats.followers > 1000 ? (stats.followers / 1000).toFixed(1) + 'k' : stats.followers}
                                            </h5>
                                            <p className={`mb-0 small ${activeTab === 'followers' ? 'text-white' : 'text-muted'}`}>Followers</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div 
                                            className={`border rounded p-3 cursor-pointer ${activeTab === 'views' ? 'bg-primary text-white' : ''}`}
                                            onClick={handleViewsClick}
                                            style={{ cursor: 'pointer' }}
                                        >
                                            <h5 className="mb-1 fw-bold">
                                                {stats.views > 1000 ? (stats.views / 1000).toFixed(1) + 'k' : stats.views}
                                            </h5>
                                            <p className={`mb-0 small ${activeTab === 'views' ? 'text-white' : 'text-muted'}`}>Views</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Profile Content */}
                <div className="row mt-4">
                    {/* Personal Information */}
                    <div className="col-xl-6 col-lg-6">
                        <div className="card">
                            <div className="card-header bg-primary-subtle">
                                <h4 className="card-title mb-0 text-primary">
                                    <i className="ri-user-line align-middle me-2"></i>
                                    Personal Information
                                </h4>
                            </div>
                            <div className="card-body">
                                <div className="pb-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Full Name</h6>
                                    <p className="fw-medium mb-0">{displayName}</p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Email Address</h6>
                                    <p className="fw-medium mb-0">
                                        <a href={`mailto:${displayEmail}`} className="text-primary">{displayEmail}</a>
                                    </p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Phone Number</h6>
                                    <p className="fw-medium mb-0">{displayPhone}</p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Platform</h6>
                                    <p className="fw-medium mb-0">{profileData.platform || 'Not specified'}</p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Account Link</h6>
                                    <p className="fw-medium mb-0">
                                        {profileData.accountLink ? (
                                            <a href={profileData.accountLink} target="_blank" rel="noopener noreferrer" className="text-primary">
                                                {profileData.accountLink}
                                            </a>
                                        ) : (
                                            'Not provided'
                                        )}
                                    </p>
                                </div>
                                
                                <div className="pt-3">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Bio</h6>
                                    <p className="fw-medium mb-0">{profileData.bio || 'No bio provided'}</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Quick Actions and Account Summary */}
                    <div className="col-xl-6 col-lg-6">
                        <div className="card">
                            <div className="card-header bg-success-subtle">
                                <h4 className="card-title mb-0 text-success">
                                    <i className="ri-settings-line align-middle me-2"></i>
                                    Quick Actions
                                </h4>
                            </div>
                            <div className="card-body">
                                <div className="d-grid gap-2">
                                    <button 
                                        className="btn btn-primary"
                                        onClick={handleEditProfileClick}
                                    >
                                        <i className="ri-edit-line me-1"></i> Edit Profile
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Account Summary */}
                        <div className="card mt-3">
                            <div className="card-header bg-info-subtle">
                                <h4 className="card-title mb-0 text-info">
                                    <i className="ri-account-circle-line align-middle me-2"></i>
                                    Account Summary
                                </h4>
                            </div>
                            <div className="card-body">
                                <div className="row g-3">
                                    <div className="col-12">
                                        <div className="d-flex justify-content-between align-items-center border-bottom pb-3">
                                            <div>
                                                <h6 className="text-muted mb-1">Total Posts</h6>
                                                <h4 className="mb-0 fw-bold text-primary">{stats.posts}</h4>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="col-12">
                                        <div className="d-flex justify-content-between align-items-center border-bottom pb-3">
                                            <div>
                                                <h6 className="text-muted mb-1">Followers</h6>
                                                <h4 className="mb-0 fw-bold text-primary">
                                                    {stats.followers > 1000 ? (stats.followers / 1000).toFixed(1) + 'k' : stats.followers}
                                                </h4>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="col-12">
                                        <div className="d-flex justify-content-between align-items-center">
                                            <div>
                                                <h6 className="text-muted mb-1">Following</h6>
                                                <h4 className="mb-0 fw-bold text-primary">0</h4>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Edit Profile Form - Only show when editing */}
                        {editing && (
                            <div className="card mt-3">
                                <div className="card-header">
                                    <h5 className="card-title mb-0">Edit Profile</h5>
                                </div>
                                <div className="card-body">
                                    <form onSubmit={handleSubmit}>
                                        <div className="mb-3">
                                            <label htmlFor="firstName" className="form-label">
                                                First Name
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="firstName"
                                                name="firstName"
                                                value={profileData.firstName}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="lastName" className="form-label">
                                                Last Name
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="lastName"
                                                name="lastName"
                                                value={profileData.lastName}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="email" className="form-label">
                                                Email
                                            </label>
                                            <input
                                                type="email"
                                                className="form-control"
                                                id="email"
                                                name="email"
                                                value={profileData.email}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="phone" className="form-label">
                                                Phone
                                            </label>
                                            <input
                                                type="tel"
                                                className="form-control"
                                                id="phone"
                                                name="phone"
                                                value={profileData.phone}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>
                                        
                                        <div className="mb-3">
                                            <label htmlFor="platform" className="form-label">
                                                Platform
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="platform"
                                                name="platform"
                                                value={profileData.platform}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>
                                        
                                        <div className="mb-3">
                                            <label htmlFor="accountLink" className="form-label">
                                                Account Link
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="accountLink"
                                                name="accountLink"
                                                value={profileData.accountLink}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="bio" className="form-label">
                                                Bio
                                            </label>
                                            <textarea
                                                className="form-control"
                                                id="bio"
                                                name="bio"
                                                rows="4"
                                                value={profileData.bio}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                                placeholder="Tell us about yourself..."
                                            ></textarea>
                                        </div>

                                        <div className="d-flex gap-2">
                                            <button
                                                type="button"
                                                className="btn btn-secondary"
                                                onClick={() => setEditing(false)}
                                                disabled={loading}
                                            >
                                                Cancel
                                            </button>
                                            <button
                                                type="submit"
                                                className="btn btn-primary"
                                                disabled={loading}
                                            >
                                                {loading ? (
                                                    <>
                                                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                        Saving...
                                                    </>
                                                ) : (
                                                    'Save Changes'
                                                )}
                                            </button>
                                        </div>
                                    </form>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Content Display Area */}
                <div className="card mt-4">
                    <div className="card-body">
                        {/* Posts Content */}
                        {activeTab === 'posts' && (
                            <div>
                                <h5 className="mb-3">My Posts</h5>
                                {reels.length === 0 ? (
                                    <div className="text-center py-5">
                                        <h6 className="text-muted">No posts found</h6>
                                        <p className="text-muted">Upload your first reel to get started.</p>
                                    </div>
                                ) : (
                                    <div className="row">
                                        {reels.map((reel) => (
                                            <div key={reel.id} className="col-xl-3 col-lg-4 col-md-6 col-sm-12 mb-4">
                                                <div className="card h-100 shadow-sm border-0 rounded">
                                                    <div className="card-body p-3">
                                                        {renderVideoPlayer(reel)}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Followers Content */}
                        {activeTab === 'followers' && (
                            <div>
                                <h5 className="mb-3">Followers</h5>
                                <div className="text-center py-5">
                                    <h6 className="text-muted">Follower list will be implemented in a future update.</h6>
                                </div>
                            </div>
                        )}

                        {/* Views Content */}
                        {activeTab === 'views' && (
                            <div>
                                <h5 className="mb-3">Reel Views</h5>
                                {reels.length === 0 ? (
                                    <div className="text-center py-5">
                                        <h6 className="text-muted">No reels found</h6>
                                    </div>
                                ) : (
                                    <div className="table-responsive">
                                        <table className="table table-centered table-nowrap mb-0">
                                            <thead className="table-light">
                                                <tr>
                                                    <th>Title</th>
                                                    <th>Views</th>
                                                    <th>Likes</th>
                                                    <th>Date</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {reels.map((reel) => (
                                                    <tr key={reel.id}>
                                                        <td>
                                                            <h6 className="mb-0">{reel.title}</h6>
                                                        </td>
                                                        <td>{reel.views || 0}</td>
                                                        <td>{reel.likes || 0}</td>
                                                        <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
